def make_transform(inp):
    """Transform: for each color with 2+ cells that shares a diagonal, extend that diagonal"""
    bg = Counter(c for row in inp for c in row).most_common(1)[0][0]

    # Group cells by color
    cells = [(r,c,inp[r][c]) for r in range(len(inp)) for c in range(len(inp[0])) if inp[r][c] != bg]
    cells_by_color = {}
    for r, c, v in cells:
        if v not in cells_by_color:
            cells_by_color[v] = []
        cells_by_color[v].append((r, c))

    # Fill grid with background
    result = [[bg] * len(inp[0]) for _ in range(len(inp))]

    # For each color with 2+ cells, extend diagonal
    for color, pairs in sorted(cells_by_color.items()):
        if len(pairs) < 2:
            continue

        r_minus_c = [p[0] - p[1] for p in pairs]
        r_plus_c = [p[0] + p[1] for p in pairs]

        is_diag = (min(r_minus_c) == max(r_minus_c))
        is_anti = (min(r_plus_c) == max(r_plus_c))

        if not (is_diag or is_anti):
            continue

        if is_diag:
            const = r_minus_c[0]
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    if r - c == const:
                        result[r][c] = color
        elif is_anti:
            const = r_plus_c[0]
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    if r + c == const:
                        result[r][c] = color

    return result

